package api

import "github.com/rh-ecosystem-edge/eco-goinfra/pkg/oran/api/internal/common"

// APIVersions is the type of the APIVersions resource returned by the API.
type APIVersions = common.APIVersions

// APIVersion is the type of an individual entry in APIVersions.ApiVersions.
type APIVersion = common.APIVersion

// AlarmDictionary is the type of the AlarmDictionary resource returned by the API.
type AlarmDictionary = common.AlarmDictionary

// AlarmDefinition is the type of an individual entry in AlarmDictionary.AlarmDefinition.
type AlarmDefinition = common.AlarmDefinition
